<!DOCTYPE html>
<html>
<head>
  <style>
    #maze { width: 400px; height: 400px; position: relative; }
    canvas { display: block; width: 100%; height: 100%; border: 1px solid black; }
    body {
      font-family: monospace;
      margin: 20px;
    }
    #completed, #timer {
      margin-top: 5px;
    }
    button#reset {
      margin-top: 10px;
      padding: 5px 10px;
    }
