<body>
  <div id="maze"><canvas></canvas></div>
  <div id="completed">0/24 completed</div>
  <div id="timer">0 ticks</div>
  <button id="reset">Reset</button>

  <script>
    (function() {
      const canvas = document.querySelector('#maze canvas');
      const ctx = canvas.getContext('2d');
      let game;
      let isRunning = false;

      window.game = {
        elapsed: 0,
        size: { rows: 15, cols: 15 },
        spawn: { r: 0, c: 0 },
        exit: { r: 0, c: 0 },
        bots: [],
        tick(n) {
          if (game && game.bots.every(b => b.finished)) return;
          for (let i = 0; i < n; i++) stepGame();
          render();
        },
        reset(seed) {
          const rows = 15, cols = 15;
          canvas.width = 400;
          canvas.height = 400;
          game = new Game(rows, cols);
          if (seed !== undefined) {
            game.seed = seed;
            window.game.seed = seed;
          } else {
            game.seed = Math.random();
            window.game.seed = undefined;
          }
          game.initMaze();
          game.initBots();
          window.game.elapsed = 0;
          render();
        },
        walls(r, c) {
          if (!game || !game.maze) return {};
          const cell = game.maze[r][c];
          return { n: cell.walls.n, e: cell.walls.e, s: cell.walls.s, w: cell.walls.w };
        }
      };

      document.getElementById('reset').addEventListener('click', () => {
        window.game.reset(window.game.seed);
      });

      function stepGame() {
        const bots = game.bots;
        let anyMoving = false;

        for (let bot of bots) {
          if (bot.finished || !bot.path.length) continue;
          const current = { r: bot.current.r, c: bot.current.c };
          const nextCell = moveBot(bot);
          if (nextCell && current.r === game.exit.r && current.c === game.exit.c) {
            bot.finished = true;
            bot.finishTick = window.game.elapsed + 1;
            document.getElementById('completed').textContent =
              `${game.bots.filter(b => b.finished).length}/24 completed`;
          }
          anyMoving = true;
        }

        if (anyMoving) {
          window.game.elapsed++;
          const allFinished = game.bots.every(b => b.finished);
          if (allFinished && isRunning) {
            setTimeout(() => { isRunning = false; }, 0);
          }
        }
      }

      function moveBot(bot) {
        const current = bot.current;
        let moved = false;

        // Logic to determine direction based on Tremaux algorithm
        const directions = ['n', 'e', 's', 'w'];
        if (bot.directionOrder.length === 0) return null;
        for (let dir of bot.directionOrder) {
          const [dr, dc] = getDirectionVector(dir);
          const nr = current.r + dr;
          const nc = current.c + dc;

          if (nr < 0 || nr >= game.maze.length || nc < 0 || nc >= game.maze[0].length) continue;
          const nextCell = { r: nr, c: nc };
          if (hasWall(current.r, current.c, dir)) continue;

          const passageKey = getPassageKey(current.r, current.c, nr, nc);
          let count = bot.passages[passageKey] || 0;

          if (count < 2) {
            if (!isVisited(nextCell, bot.path)) {
              // Unvisited cell
              bot.current = nextCell;
              bot.path.push({ ...nextCell });
              bot.passages[passageKey] = count + 1;
              moved = true;
              break;
            } else {
              const lastIdx = bot.path.length - 1;
              if (lastIdx >= 0 && 
                  current.r === bot.path[lastIdx].r &&
                  current.c === bot.path[lastIdx].c) {
                // Prevent infinite loop
                continue;
              }
              if (bot.path.length > 1 && 
                  nextCell.r === bot.path[bot.path.length - 2].r &&
                  nextCell.c === bot.path[bot.path.length - 2].c) {
                // Backtrack to previous cell
                bot.current = nextCell;
                bot.path.push({ ...nextCell });
                bot.passages[passageKey] = count + 1;
                moved = true;
                break;
              }
            }
          }
        }

        if (!moved && bot.path.length > 1) {
          // Backtrack
          const prev = bot.path[bot.path.length - 2];
          const passageKey = getPassageKey(current.r, current.c, prev.r, prev.c);
          let count = bot.passages[passageKey] || 0;
          if (count < 2) {
            bot.current = { r: prev.r, c: prev.c };
            bot.path.push({ ...prev });
            bot.passages[passageKey] = count + 1;
            moved = true;
          } else {
            // Mark dead end
            const deadKey = `${current.r},${current.c}`;
            if (!bot.deadEnds.includes(deadKey)) {
              bot.deadEnds.push(deadKey);
            }
          }
        }

        return moved ? { r: bot.current.r, c: bot.current.c } : null;
      }

      function hasWall(r, c, dir) {
        const cell = game.maze[r][c];
        if (dir === 'n') return cell.walls.n;
        if (dir === 'e') return cell.walls.e;
        if (dir === 's') return cell.walls.s;
        if (dir === 'w') return cell.walls.w;
      }

      function getDirectionVector(dir) {
        switch (dir) {
          case 'n': return [-1, 0];
          case 'e': return [0, 1];
          case 's': return [1, 0];
          case 'w': return [0, -1];
        }
      }

      function getPassageKey(r1, c1, r2, c2) {
        return `${Math.min(r1, r2)},${Math.min(c1, c2)}-${Math.max(r1, r2)},${Math.max(c1, c2)}`;
      }

      function isVisited(nextCell, path) {
        const key = `${nextCell.r},${nextCell.c}`;
        for (let p of path) {
          if (`${p.r},${p.c}` === key) return true;
        }
        return false;
      }

      function render() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        const rows = game.maze.length;
        const cols = game.maze[0].length;
        const cellSizeW = canvas.width / cols;
        const cellSizeH = canvas.height / rows;

        // Draw walls
        for (let r = 0; r < rows; r++) {
          for (let c = 0; c < cols; c++) {
            ctx.strokeStyle = '#333';
            if (game.maze[r][c].walls.n) drawLine(c, r, 'n', cellSizeW, cellSizeH);
            if (game.maze[r][c].walls.e) drawLine(c, r, 'e', cellSizeW, cellSizeH);
            if (game.maze[r][c].walls.s) drawLine(c, r, 's', cellSizeW, cellSizeH);
            if (game.maze[r][c].walls.w) drawLine(c, r, 'w', cellSizeW, cellSizeH);
          }
        }

        // Draw exit
        ctx.fillStyle = 'lime';
        const exitCell = game.exit;
        ctx.fillRect(exitCell.c * cellSizeW + 5, exitCell.r * cellSizeH + 5,
                     cellSizeW - 10, cellSizeH - 10);

        // Draw bots
        for (let bot of game.bots) {
          if (!bot.path.length || bot.finished) continue;
          const current = bot.path[bot.path.length - 1];
          const x = current.c * cellSizeW + cellSizeW / 2;
          const y = current.r * cellSizeH + cellSizeH / 2;
          ctx.fillStyle = bot.color;
          ctx.beginPath();
          ctx.arc(x, y, 3, 0, Math.PI * 2);
          ctx.fill();
        }
      }

      function drawLine(c, r, dir, w, h) {
        const x = c * w;
        const y = r * h;
        if (dir === 'n') ctx.fillRect(x, y, w, 1);
        else if (dir === 'e') ctx.fillRect(x + w, y, 1, h);
        else if (dir === 's') ctx.fillRect(x, y + h, w, 1);
        else if (dir === 'w') ctx.fillRect(x, y, 1, h);
      }

      function createSeededRandom(seed) {
        let x = seed;
        return () => {
          x = (x * 9301 + 49297) % 233280;
          return x / 233280;
        };
      }

      class Game {
        constructor(rows, cols) {
          this.rows = rows;
          this.cols = cols;
          this.seed = Math.random();
          this.maze = null;
          this.spawn = { r: 0, c: 0 };
          this.exit = { r: 0, c: 0 };
          this.bots = [];
        }

        initMaze() {
          const random = createSeededRandom(this.seed);
          this.maze = generateMaze(this.rows, this.cols, random);
          // Place exit
          let exitR, exitC;
          do {
            exitR = Math.floor(random() * this.rows);
            exitC = Math.floor(random() * this.cols);
          } while (exitR === 0 && exitC === 0); // Not spawn
          this.exit = { r: exitR, c: exitC };
        }

        initBots() {
          const botColors = generateBotColors(24);
          for (let i = 0; i < 24; i++) {
            const randomizer = createSeededRandom(this.seed + i);
            const dirs = ['n', 'e', 's', 'w'];
            let directionOrder = shuffle([...dirs], randomizer);
            this.bots.push({
              id: i,
              color: botColors[i],
              current: { r: 0, c: 0 },
              path: [{ r: 0, c: 0 }],
              passages: {},
              deadEnds: [],
              directionOrder
            });
          }
        }
      }

      function generateBotColors(n) {
        const colors = [];
        for (let i = 0; i < n; i++) {
          const hue = (360 * i / n) % 360;
          colors.push(`hsl(${hue}, 100%, 50%)`);
        }
        return colors;
      }

      function generateMaze(rows, cols, randomizer) {
        const maze = Array.from({ length: rows }, () =>
          Array.from({ length: cols }, () => ({
            walls: { n: true, e: true, s: true, w: true }
          }))
        );
        const visited = new Set();
        function visit(r, c) {
          visited.add(`${r},${c}`);
          const directions = [
            [ -1, 0 ], // North
            [ 0, 1 ],  // East
            [ 1, 0 ],  // South
            [ 0, -1 ]  // West
          ];
          shuffle(directions, randomizer);

          for (let [dr, dc] of directions) {
            const nr = r + dr;
            const nc = c + dc;
            if (
              nr >= 0 && nr < rows &&
              nc >= 0 && nc < cols &&
              !visited.has(`${nr},${nc}`)
            ) {
              // Remove wall
              if (dr === -1) { maze[r][c].walls.n = false; maze[nr][nc].walls.s = false; }
              else if (dc === 1) { maze[r][c].walls.e = false; maze[nr][nc].walls.w = false; }
              else if (dr === 1) { maze[r][c].walls.s = false; maze[nr][nc].walls.n = false; }
              else if (dc === -1) { maze[r][c].walls.w = false; maze[nr][nc].walls.e = false; }

              visit(nr, nc);
            }
          }
        }

        function shuffle(arr, randomizer) {
          for (let i = arr.length - 1; i > 0; i--) {
            const j = Math.floor(randomizer() * (i + 1));
            [arr[i], arr[j]] = [arr[j], arr[i]];
          }
        }

        visit(0, 0);
        return maze;
      }

      function shuffle(arr, randomizer) {
        for (let i = arr.length - 1; i > 0; i--) {
          const j = Math.floor(randomizer() * (i + 1));
          [arr[i], arr[j]] = [arr[j], arr[i]];
        }
      }

      window.game.reset();
    })();
  </script>
